# Generated by tools/build-launcher.ps1. Edit tools/launcher.template.ps1 instead.
& {
[CmdletBinding()]
param([ValidateSet('menu','console','gui','check','othergui','crisgui','crisinstall','crisswitch','apargui')][string]$Mode='menu')
$ErrorActionPreference='Stop'
if($env:OS -ne 'Windows_NT'){throw 'This tool requires Windows.'}
if($ExecutionContext.SessionState.LanguageMode -ne 'FullLanguage'){throw 'Organization policy restricts this session. Ask IT to approve the tool.'}
$script:DscLauncherHash='@ENGINE_SHA256@'
$script:DscLauncherUrl='https://raw.githubusercontent.com/girishtiwari007/DSC-FIXER/main/troubleshooter.ps1'
$script:DscLauncherCache=$null
$script:DscLauncherTheme=$null
$script:DscLauncherRoot=$PSScriptRoot
$script:DscLauncherDirectory=$null
function Write-DscLauncherEvent([string]$Operation,$Data) {
    if(-not $script:DscLauncherDirectory){return}
    $event=[ordered]@{Utc=[DateTime]::UtcNow.ToString('o');Operation=$Operation;Data=$Data}
    try{Add-Content -LiteralPath (Join-Path $script:DscLauncherDirectory 'launcher.jsonl') -Value ($event|ConvertTo-Json -Compress -Depth 5) -Encoding UTF8}catch{Write-Warning 'Unable to update the launcher log.'}
}
foreach($root in @($env:LOCALAPPDATA,$env:TEMP)){
    if(-not $root){continue}
    try{
        $script:DscLauncherDirectory=Join-Path $root ('DSC-Signer-Fixer\sessions\launcher-'+(Get-Date -Format 'yyyyMMdd-HHmmss')+'-'+[guid]::NewGuid().ToString('N'))
        [void][IO.Directory]::CreateDirectory($script:DscLauncherDirectory)
        break
    }catch{$script:DscLauncherDirectory=$null}
}
if(-not $script:DscLauncherDirectory){throw 'Unable to create a local launcher log. No troubleshooter was started.'}
Write-DscLauncherEvent 'Launcher started' @{Mode=$Mode}
function Get-DscLauncherHash([byte[]]$Bytes) {
    $sha=[Security.Cryptography.SHA256]::Create()
    try{return ([BitConverter]::ToString($sha.ComputeHash($Bytes))).Replace('-','')}finally{$sha.Dispose()}
}
function Get-DscLauncherDownload {
    [Net.ServicePointManager]::SecurityProtocol=[Net.ServicePointManager]::SecurityProtocol -bor 3072
    $client=New-Object Net.WebClient
    $client.Proxy=[Net.WebRequest]::GetSystemWebProxy()
    if($client.Proxy){$client.Proxy.Credentials=[Net.CredentialCache]::DefaultCredentials}
    $watch=[Diagnostics.Stopwatch]::StartNew()
    try{
        $task=$client.DownloadDataTaskAsync([Uri]$script:DscLauncherUrl)
        while(-not $task.IsCompleted){
            Write-Progress -Activity 'Downloading selected troubleshooter' -Status ('Elapsed: '+[int]$watch.Elapsed.TotalSeconds+' seconds. Waiting for GitHub...')
            if($watch.Elapsed.TotalSeconds -ge 90){$client.CancelAsync();throw 'Download timed out after 90 seconds.'}
            Start-Sleep -Milliseconds 200
        }
        $bytes=$task.GetAwaiter().GetResult()
        Write-Host ('Downloaded in '+[math]::Round($watch.Elapsed.TotalSeconds,1)+' seconds. Validating...') -ForegroundColor Cyan
        Write-DscLauncherEvent 'Engine downloaded' @{Bytes=$bytes.Length;Seconds=$watch.Elapsed.TotalSeconds}
        return ,$bytes
    }finally{Write-Progress -Activity 'Downloading selected troubleshooter' -Completed;$client.Dispose()}
}
function Get-DscLauncherEngine {
    if($script:DscLauncherCache){return $script:DscLauncherCache}
    $bytes=$null
    # A checked-out repository can run locally without another download.
    if($script:DscLauncherRoot){
        $local=Join-Path $script:DscLauncherRoot 'troubleshooter.ps1'
        if(Test-Path -LiteralPath $local -PathType Leaf){
            $candidate=[IO.File]::ReadAllBytes($local)
            if((Get-DscLauncherHash $candidate) -eq $script:DscLauncherHash){$bytes=$candidate;Write-DscLauncherEvent 'Verified local engine selected' @{Path=$local}}
        }
    }
    if($null -eq $bytes){$bytes=Get-DscLauncherDownload}
    if((Get-DscLauncherHash $bytes) -ne $script:DscLauncherHash){throw 'Troubleshooter integrity check failed. Nothing was executed. Reload the online command and retry; GitHub may still be updating.'}
    $text=[Text.Encoding]::UTF8.GetString($bytes).TrimStart([char]0xFEFF)
    $tokens=$null;$errors=$null
    [void][Management.Automation.Language.Parser]::ParseInput($text,[ref]$tokens,[ref]$errors)
    if($errors.Count){throw 'Downloaded troubleshooter contains invalid PowerShell. Nothing was executed.'}
    $script:DscLauncherCache=$text
    return $text
}
function Invoke-DscSelectedEngine([string]$Text,[string]$Selection) {
    & ([scriptblock]::Create($Text)) -Mode $Selection
}
function Invoke-DscSelection([ValidateSet('console','gui','check','othergui','crisgui','crisinstall','crisswitch','apargui')][string]$Selection) {
    $names=@{console='E-Office console';gui='E-Office 4.1.8 GUI';check='Read-only checks';othergui='Java and website settings GUI';crisgui='CRIS Signer Switcher';crisinstall='CRIS installer';crisswitch='Desktop CRIS switcher';apargui='APAR Signer Service 7.0.2 GUI'}
    Write-Host ('Loading '+$names[$Selection]+' ...') -ForegroundColor Cyan
    Write-DscLauncherEvent 'Option selected' @{Mode=$Selection}
    try{
        $engine=Get-DscLauncherEngine
        Invoke-DscSelectedEngine $engine $Selection
        Write-DscLauncherEvent 'Selected troubleshooter returned' @{Mode=$Selection}
    }catch{
        Write-DscLauncherEvent 'Launch failed' @{Mode=$Selection;Message=$_.Exception.Message}
        Write-Host ('Unable to open the selected troubleshooter: '+$_.Exception.Message) -ForegroundColor Yellow
        Write-Host 'Retry the option or rerun the online command. Check your internet/proxy connection. If policy blocks the tool, contact IT.'
    }
}
# @MENU@
try{
    if($Mode -ne 'menu'){Invoke-DscSelection $Mode;return}
    while($true){
        Show-DscMenu
        Write-Host 'Select any one option (1-7):' -ForegroundColor Black -BackgroundColor Yellow
        switch(Read-Host 'Choose 1-7'){
            '1' {Invoke-DscSelection 'console'}
            '2' {Invoke-DscSelection 'gui'}
            '3' {Invoke-DscSelection 'othergui'}
            '4' {continue}
            '5' {Invoke-DscSelection 'crisgui'}
            '6' {Invoke-DscSelection 'apargui'}
            '7' {return}
            default {Write-Host 'Enter a number from 1 to 7.' -ForegroundColor Yellow}
        }
    }
}finally{Write-DscLauncherEvent 'Launcher closed' @{};
    if($script:DscLauncherTheme){try{$Host.UI.RawUI.BackgroundColor=$script:DscLauncherTheme.Background;$Host.UI.RawUI.ForegroundColor=$script:DscLauncherTheme.Foreground;$Host.UI.RawUI.WindowTitle=$script:DscLauncherTheme.Title}catch{};$script:DscLauncherTheme=$null}
    Write-Host ('Launcher logs: '+$script:DscLauncherDirectory)
}
} @args
